B.ad_=new A.bf("Hi\u1ec7n v\u1eadt ch\u01b0a c\xf3 n\u1ed9i dung \u0111\u01b0\u1ee3c xu\u1ea5t b\u1ea3n.",B.H,null)
B.ad0=new A.bf("M\u1ee5c \u0111\xe3 l\u01b0u, hi\u1ec7n v\u1eadt v\u1eeba m\u1edf v\xe0 k\u1ebft qu\u1ea3 th\u1eed t\xe0i m\u1eabu ch\u1ec9 gi\u1eef trong phi\xean. L\u01b0\u1ee3t tham quan, \u0111\u01a1n h\xe0ng, \u0111i\u1ec3m v\xe0 huy hi\u1ec7u \u0111\u01b0\u1ee3c t\u1ea3i t\u1eeb h\u1ec7 th\u1ed1ng.",B.H,null)
B.ad1=new A.bf("N\u1ebfu \u0111\u1ed9 t\u01b0\u01a1ng \u0111\u1ed3ng ch\u01b0a \u0111\u1ee7 cao, h\u1ec7 th\u1ed1ng s\u1ebd \u0111\u1ec1 ngh\u1ecb x\xe1c nh\u1eadn ho\u1eb7c khuy\u1ebfn ngh\u1ecb qu\xe9t m\xe3 QR c\u1ea1nh hi\u1ec7n v\u1eadt.",B.H,null)
B.ad2=new A.bf("Ch\u01b0a c\xf3 tuy\u1ebfn \u0111\xe3 xu\u1ea5t b\u1ea3n ph\xf9 h\u1ee3p.",B.H,null)
B.ad3=new A.bf("Ch\u01b0a c\xf3 y\xeau c\u1ea7u thanh to\xe1n.",B.H,null)
B.ad4=new A.bf("Ch\u1ec9 chia s\u1ebb m\xe3 v\u1edbi ng\u01b0\u1eddi c\xf9ng nh\xf3m. T\u1ea1o m\xe3 m\u1edbi s\u1ebd thay th\u1ebf m\xe3 c\u0169; th\xe0nh vi\xean nh\u1eadp m\xe3 trong m\u1ee5c D\u1ecbch v\u1ee5 c\u1ee7a t\xf4i.",B.H,null)
B.ad5=new A.bf("Hi\u1ec7n v\u1eadt ch\u01b0a c\xf3 b\u1ea3n thuy\u1ebft minh \u0111\u01b0\u1ee3c xu\u1ea5t b\u1ea3n.",B.H,null)
B.ad6=new A.bf("C\xe1c b\u1ea3o t\xe0ng kh\xe1c s\u1ebd xu\u1ea5t hi\u1ec7n khi \u0111\u01b0\u1ee3c c\xf4ng khai tr\xean h\u1ec7 th\u1ed1ng.",B.H,null)
B.ad7=new A.bf("Ch\u01b0a c\xf3 d\u1eef li\u1ec7u.",B.H,null)
B.ad8=new A.bf("B\u1ea1n ch\u01b0a g\u1eedi y\xeau c\u1ea7u n\xe0o.",B.H,null)
B.ad9=new A.bf("H\u1ecfi \u0111\xe1p m\u1eabu t\u1eeb n\u1ed9i dung b\u1ed9 s\u01b0u t\u1eadp. Tr\u1ee3 l\xfd th\xf4ng minh s\u1ebd \u0111\u01b0\u1ee3c k\u1ebft n\u1ed1i sau.",B.H,null)
B.ada=new A.bf("D\u1eef li\u1ec7u k\u1ebft n\u1ed1i tr\u1ef1c ti\u1ebfp t\u1eeb m\xe1y ch\u1ee7 Smart Museum Guide System.",B.H,null)
B.adb=new A.bf("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.H,null)
B.add=new A.bf("Nh\u1eadp m\xe3 do ng\u01b0\u1eddi mua g\xf3i nh\xf3m chia s\u1ebb \u0111\u1ec3 nh\u1eadn quy\u1ec1n truy c\u1eadp.",B.H,null)
B.ade=new A.bf("Gi\xe1 v\xe0 th\u1eddi h\u1ea1n \u0111\u01b0\u1ee3c m\xe1y ch\u1ee7 x\xe1c nh\u1eadn khi t\u1ea1o \u0111\u01a1n. Quy\u1ec1n truy c\u1eadp ch\u1ec9 \u0111\u01b0\u1ee3c c\u1ea5p sau khi m\xe1y ch\u1ee7 x\xe1c nh\u1eadn thanh to\xe1n.",B.H,null)
B.adf=new A.bf("Xem hi\u1ec7n v\u1eadt n\u1eb1m \u1edf ph\xf2ng v\xe0 t\u1ea7ng n\xe0o. Qu\xe9t QR t\u1ea1i v\u1ecb tr\xed \u0111ang \u0111\u1ee9ng \u0111\u1ec3 t\xecm \u0111\u01b0\u1eddng tr\xean s\u01a1 \u0111\u1ed3.",B.H,null)
B.adg=new A.bf("Ch\u01b0a c\xf3 b\u1ea3o t\xe0ng c\xf4ng khai.",B.H,null)
B.adh=new A.bf("\u0110\xe3 ghi nh\u1eadn l\u01b0\u1ee3t qu\xe9t. C\xe2u \u0111\u1ed1 v\xe0 \u0111i\u1ec3m \u0111\u01b0\u1ee3c h\u1ec7 th\u1ed1ng c\u1eadp nh\u1eadt n\u1ebfu \u0111\u1ee7 \u0111i\u1ec1u ki\u1ec7n.",B.H,null)
B.adi=new A.bf("L\u01b0\u1ee3t tham quan t\u1ef1 do. Qu\xe9t QR t\u1ea1i hi\u1ec7n v\u1eadt \u0111\u1ec3 ghi nh\u1eadn kh\xe1m ph\xe1.",B.H,null)
B.adj=new A.bf("Ch\u01b0a c\xf3 n\u1ed9i dung c\u1ee7a g\xf3i.",B.H,null)
B.adk=new A.bf("C\xe2u h\u1ecfi \u0111\u01b0\u1ee3c m\u1edf sau khi h\u1ec7 th\u1ed1ng ghi nh\u1eadn b\u1ea1n qu\xe9t hi\u1ec7n v\u1eadt c\xf3 b\u1ed9 c\xe2u h\u1ecfi \u0111\xe3 xu\u1ea5t b\u1ea3n.",B.H,null)
B.adl=new A.bf("Ch\u01b0a c\xf3 quy\u1ec1n truy c\u1eadp \u0111\u01b0\u1ee3c c\u1ea5p.",B.H,null)
B.adn=new A.bf("B\u1ea1n c\xf3 th\u1ec3 tra c\u1ee9u b\u1ed9 s\u01b0u t\u1eadp m\xe0 kh\xf4ng c\u1ea7n c\u1ea5p quy\u1ec1n m\xe1y \u1ea3nh.",B.H,null)
B.ado=new A.bf("Tr\u1ea3i nghi\u1ec7m m\xf4 ph\u1ecfng tr\xean web, kh\xf4ng s\u1eed d\u1ee5ng m\xe1y \u1ea3nh.",B.H,null)
B.adp=new A.bf("Hi\u1ec7n v\u1eadt m\u1eabu ch\u01b0a c\xf3 v\u1ecb tr\xed trong b\u1ea3o t\xe0ng th\u1ef1c t\u1ebf.",B.H,null)
B.adr=new A.bf("\u0110\xe1nh gi\xe1 b\u1ea3o t\xe0ng c\u1ea7n g\u1eafn v\u1edbi l\u01b0\u1ee3t tham quan \u0111\xe3 ho\xe0n th\xe0nh. G\xf3p \xfd chung s\u1ebd \u0111\u01b0\u1ee3c g\u1eedi \u0111\u1ebfn b\u1ed9 ph\u1eadn h\u1ed7 tr\u1ee3.",B.H,null)
B.ads=new A.bf("Hi\u1ec7n v\u1eadt ch\u01b0a \u0111\u01b0\u1ee3c li\xean k\u1ebft v\u1edbi \u0111i\u1ec3m \u0111\u1ebfn tr\xean s\u01a1 \u0111\u1ed3 \u0111\xe3 xu\u1ea5t b\u1ea3n.",B.H,null)
B.adt=new A.bf("C\xe1c h\xe0nh tr\xecnh \u0111\u01b0\u1ee3c t\u1ea3i t\u1eeb m\xe1y ch\u1ee7 v\xe0 l\u1ecdc theo th\u1eddi gian. S\u1edf th\xedch ch\u01b0a \u0111\u01b0\u1ee3c m\xe1y ch\u1ee7 h\u1ed7 tr\u1ee3 l\u1ecdc.",B.H,null)
